def parse_time(h, m, period):
    h = h % 24
    p = period.strip().upper()
    if p.startswith('P'):
        if h != 12:
            h += 12
    else:
        if h == 12:
            h = 0
    return h * 60 + m

def format_time(total):
    total = total % (24 * 60)
    h, m = divmod(total, 60)
    period = 'AM' if h < 12 else 'PM'
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{period}"

